ROWS = [
dict(id="T123", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'Nonuniqueness of percolation on nonamenable quasi-transitive graphs' (24 Sep 2026, github.com/openai/math), Theorem 1.1 and its corollary, claims a bound on the critical connection operator giving the triangle condition and the mean-field exponents on every connected, locally finite, quasi-transitive nonamenable graph; Lean files are supplied. AI-written and unrefereed; this records the claim, not a check of the proof. Replacement row to be screened.", d="PERC", t="Mean-field critical behaviour of percolation on every nonamenable transitive graph",
 s="For Bernoulli bond percolation on any connected, locally finite, quasi-transitive nonamenable graph, the triangle condition holds at p_c, Σ_{x,y} τ_{p_c}(o,x) τ_{p_c}(x,y) τ_{p_c}(y,o) < ∞, and consequently the critical exponents take their mean-field values (β = γ = 1, δ = 2).",
 c="A stronger form asks for p_c < p_{2→2}, the threshold at which the percolation operator stops being bounded on ℓ², which implies the triangle condition (Hutchcroft).",
 src="T. Hutchcroft, Percolation on hyperbolic graphs, Geom. Funct. Anal. 29 (2019) 766–810, arXiv:1804.10191 (the triangle condition for hyperbolic graphs); I. Benjamini and O. Schramm, Percolation beyond Z^d, many questions and a few answers, Electron. Comm. Probab. 1 (1996)",
 why="Nonamenability is expected to make percolation behave like percolation on a tree at criticality in every dimension; together with p_c < p_u (T004) this is the central conjecture of percolation beyond Euclidean lattices.",
 st="Proved for highly nonamenable graphs (Schonmann 2001; every nonamenable group has such a Cayley graph, Pak–Smirnova-Nagnibeda 2000), for products of trees (Kozma 2011), for nonunimodular transitive graphs (Hutchcroft, J. Amer. Math. Soc. 33 (2020) 1101–1165) and for Gromov-hyperbolic graphs (Hutchcroft, arXiv:1804.10191). Continuity θ(p_c) = 0 holds on all unimodular nonamenable transitive graphs (Benjamini–Lyons–Peres–Schramm 1999). Open in general, for example for many Cayley graphs of nonamenable groups with amenable-looking geometry.",
 n="Status updated after the w673 audit (14 Oct)."),
dict(id='T124',
 x='Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Expansion in SL_2(F_p) is group theory and additive combinatorics.',
 d='RW',
 t='Uniform expansion of SL_2(F_p) for all generating sets',
 s='There is ε > 0 such that for every prime p and every pair of elements generating SL_2(F_p), the Cayley graph of SL_2(F_p) with respect to that pair and its inverses has spectral gap at least ε; equivalently, the lazy random walk mixes in O(log p) steps uniformly over generating pairs.',
 c="Lubotzky's question; the generators are allowed to depend on p, which is what makes uniformity hard.",
 src='A. Lubotzky, Discrete Groups, Expanding Graphs and Invariant Measures (Birkhäuser, 1994); E. Breuillard and A. Gamburd, Strong uniform expansion in SL(2,p), Geom. Funct. Anal. 20 (2010), arXiv:0911.3022 (expansion for all generating pairs, for a density-one set of primes)',
 why='Expansion of Cayley graphs of finite simple groups is the meeting point of random walks, additive combinatorics and number theory (affine sieve, superstrong approximation); uniformity over generators asks whether expansion is a property of the group alone.',
 st='Bourgain and Gamburd (Ann. Math. 2008) proved expansion for fixed generators in SL_2(Z) generating a non-elementary subgroup, reduced mod p. Breuillard and Gamburd (arXiv:0911.3022) proved uniform expansion over all generating pairs for a set of primes of density one, and random pairs give expanders with probability tending to one (Breuillard–Green–Guralnick–Tao, J. Eur. Math. Soc. 17 (2015) 1367–1434). Uniform expansion over all primes is open.',
 n='Status updated after the w673 audit (14 Oct).'),
dict(id="T125", d="RW", t="Superdiffusivity of the two-dimensional self-repelling Brownian polymer",
 s="For the self-repelling Brownian polymer in two dimensions (a Brownian particle pushed down the gradient of its own occupation measure smoothed by a fixed smooth, positive-definite potential V), with fixed coupling and started from its stationary environment (Tóth–Valkó), E|X(t)|² is of order t (log t)^{1/2}.",
 c="The (log t)^{1/2} correction comes from a renormalization-group argument; the discrete true self-avoiding walk is a separate model with the same prediction. In one dimension the exponent is 2/3 and in three or more dimensions the motion is diffusive. Cannizzaro and Giles (arXiv:2403.06730) state the fixed-coupling exponent as unknown.",
 src="D. J. Amit, G. Parisi and L. Peliti, Asymptotic behavior of the 'true' self-avoiding walk, Phys. Rev. B 27 (1983); S. P. Obukhov and L. Peliti, Renormalisation of the 'true' self-avoiding walk, J. Phys. A 16 (1983)",
 why="Self-repelling motion is the simplest model of a walk interacting with its own past, and two dimensions is its critical dimension; the same logarithmic superdiffusivity is predicted for diffusion in random divergence-free fields and for the anisotropic KPZ equation.",
 st="Tóth and Valkó (J. Stat. Phys. 2012) proved superdiffusive bounds between t log log t and t log t for the self-repelling Brownian polymer. The (log t)^{1/2} law is proved for a Brownian particle in the curl of the two-dimensional Gaussian free field (Cannizzaro–Haunschmid-Sibitz–Toninelli, Ann. Probab. 50 (2022) 2475–2498), and in the weak-coupling limit of the polymer, with an explicit diffusivity (Cannizzaro–Giles, arXiv:2403.06730). The fixed-coupling (log t)^{1/2} law is open. In one dimension the scaling limit of the true self-repelling motion is known (Tóth–Werner 1998).",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T126", d="IPS", t="Anomalous heat conduction in one-dimensional anharmonic chains",
 s="For a one-dimensional chain of anharmonic oscillators with nearest-neighbour interactions conserving energy, momentum and stretch, with a generic potential (an FPUT chain with nonzero cubic coupling, at nonzero pressure), the heat conductivity of a chain of length L between Langevin reservoirs grows like L^{1/3}, and in equilibrium the heat mode of the energy correlations spreads as a 5/3-stable Lévy process, while the two sound modes, moving at ±c, have KPZ scaling.",
 c="These are predictions of Spohn's nonlinear fluctuating hydrodynamics (arXiv:1305.6412, eqs. (3.14) and (4.11)–(4.13)) and of mode coupling, not theorems; chains with special symmetry (for instance zero pressure) are predicted to fall into other classes.",
 src="S. Lepri, R. Livi and A. Politi, Heat conduction in chains of nonlinear oscillators, Phys. Rev. Lett. 78 (1997); H. Spohn, Nonlinear fluctuating hydrodynamics for anharmonic chains, J. Stat. Phys. 154 (2014)",
 why="Anomalous conduction is the one-dimensional face of the problem of deriving Fourier's law (T033); it is observed in simulations and in nanotubes, and it is the cleanest prediction of KPZ physics in a deterministic Hamiltonian system.",
 st="For harmonic chains with momentum-conserving noise the conductivity grows like L^{1/2} (Basile–Bernardin–Olla 2006, 2009), and energy fluctuations follow a 3/4-fractional heat equation (Jara–Komorowski–Olla, Comm. Math. Phys. 339 (2015) 407–453; Bernardin–Gonçalves–Jara, Arch. Ration. Mech. Anal. 220 (2016) 505–542). For anharmonic chains, deterministic or with noise, the L^{1/3} law and the 5/3-Lévy heat mode are open. Normal conduction for pinned chains is T033.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T127", d="TREE", t="Recurrence of the frog model on 3-ary and 4-ary trees",
 s="On the rooted d-ary tree, place one sleeping frog at each vertex and an active frog at the root; active frogs perform independent simple random walks and wake every frog they visit. Decide for d = 3 and d = 4 whether the root is visited infinitely often almost surely (recurrence) or finitely often (transience).",
 c="Hoffman, Johnson and Junge settled d = 2 and d ≥ 5 and left the two middle cases; the problem is to find the transition.",
 src="C. Hoffman, T. Johnson and M. Junge, Recurrence and transience for the frog model on trees, Ann. Probab. 45 (2017)",
 why="The frog model is the basic model of a self-amplifying spread of random walkers (rumour and infection models); on trees the competition between branching of the walkers and transience of each walk is sharp, and the open cases sit exactly at the phase transition.",
 st="Recurrent for d = 2 and transient for d ≥ 5 (Hoffman–Johnson–Junge, arXiv:1404.6238); with Poisson(μ) sleeping frogs per site the critical μ is known to grow linearly in d (Johnson–Junge, Electron. Commun. Probab. 21 (2016)). Mathews (arXiv:2309.14443) still treats d = 3 and d = 4 as known only from simulation. With one frog per site, d = 3 and d = 4 are open.",
 n="Status updated after the w673 audit (14 Oct). Fame borderline in that audit; kept for now."),
dict(id="T128", d="RMT", t="Random band matrices at the critical bandwidth",
 s="Let H be the real symmetric N × N band matrix with independent centred Gaussian entries h_ij (i ≤ j) of variance 1/(2W + 1) when the periodic distance |i − j|_N is at most W, and zero otherwise, and take W = c√N with c fixed. For every energy E in (−2, 2), the eigenvalues near E, unfolded by the semicircle density, converge as N → ∞ to a point process that depends on c and E through a single crossover parameter and interpolates between Poisson (c → 0) and GOE (c → ∞), as predicted by the supersymmetric sigma model.",
 c="The localized (W ≪ √N) and delocalized (W ≫ √N) sides are now known; this row asks only for the critical regime, which the retired row T035 does not cover.",
 src="Y. V. Fyodorov and A. D. Mirlin, Scaling properties of localization in random band matrices: a σ-model approach, Phys. Rev. Lett. 67 (1991)",
 why="It is the one-dimensional model case of the Anderson transition in finite volume: a one-parameter family of critical statistics between localization and random-matrix behaviour.",
 st="Both sides of the transition are proved (T035, retired): delocalization with Wigner–Dyson statistics for W ≫ √N (Yau–Yin, arXiv:2501.01718; Erdős–Riabov, arXiv:2506.06441) and localization at scale W² for W² ≪ N (Drogin, arXiv:2508.05802), with Poisson bulk statistics for real Gaussian band matrices when W² ≪ N/log N (Fan–Zou, arXiv:2609.23389). In a sigma-model approximation of Gaussian block band matrices the crossover at W ~ √N has been studied by M. Shcherbina and T. Shcherbina (arXiv:1802.03813, continuing J. Stat. Phys. 164 (2016) and Comm. Math. Phys. 351 (2017)). For complex Gaussian band matrices in the periodic block form of Yau and Yin, Ghosal and Remy (arXiv:2611.15085) prove that at N/W² → τ the rescaled bulk eigenvalues and the block-mass profiles of the eigenvectors converge jointly to a law determined by the DMPK diffusion of the unitary class, which tends to the sine process as τ → 0 and to Poisson as τ → ∞. The limiting statistics at W = c√N for the real symmetric model of the statement, with its sharp band profile, are open.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T129", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'The sharp exponential rate of singularity for symmetric Bernoulli matrices' (3 Oct 2026, Thm 1.1) claims P(det A_n = 0) = (1/2 + o(1))^n for the uniform symmetric sign model. AI-written and unrefereed; this records the claim, not a check of the proof. Replacement row to be screened.", d="RMT", t="The singularity probability of random symmetric sign matrices",
 s="Let A_n be a uniformly random symmetric n × n matrix with independent ±1 entries on and above the diagonal. Then P(A_n is singular) = (1/2 + o(1))^n.",
 c="The non-symmetric analogue, P(singular) = (1/2 + o(1))^n for ±1 matrices, is Tikhomirov's theorem; the symmetric case loses the independence between a row and its column that the non-symmetric proofs use. A sharper form, that two equal or opposite rows are the dominant cause, so that the probability is of order n² 2^{−n}, is a stronger target that needs its own source.",
 src="K. P. Costello, T. Tao and V. Vu, Random symmetric matrices are almost surely nonsingular, Duke Math. J. 135 (2006); V. H. Vu, Recent progress in combinatorial random matrix theory, Probab. Surv. 18 (2021) 179–200",
 why="Invertibility of random discrete matrices is the core of non-asymptotic random matrix theory and of Littlewood–Offord theory; the symmetric case is the natural test because the dependence breaks the methods that solved the non-symmetric problem.",
 st="Costello–Tao–Vu (2006) proved o(1); the bound was improved to n^{−C} (Nguyen 2012), exp(−n^c) (Vershynin 2014), exp(−c√n) (Campos–Mattos–Morris–Morrison 2021) and exp(−cn) (Campos–Jenssen–Michelen–Sahasrabudhe, arXiv:2105.11384, J. Amer. Math. Soc. 38), who also bound the least singular value by Cε + exp(−cn) and the probability of a repeated eigenvalue by exp(−Ω(n)) (arXiv:2203.06141); corank estimates are in arXiv:2506.01155, and Liang, Yu and Yu (arXiv:2610.39424) give P(rank ≤ n − k) ≤ 2e^{−cnk} for every 1 ≤ k ≤ n with a new proof of the exponential bound. The base 1/2 is open. For non-symmetric ±1 matrices the base 1/2 is proved (Tikhomirov, Ann. Math. 2020), with sharper forms for general discrete entries by Jain, Sah and Sawhney (Geom. Funct. Anal. 31 (2021)).",
 n="Status updated after the w673 audit (14 Oct).",
 loc="Vu, Probab. Surv. 18 (2021), arXiv:2005.02797, Conjecture 3.3"),
dict(id="T130", d="SM", t="The dynamic critical exponent of the two-dimensional Ising model",
 s="For continuous-time heat-bath Glauber dynamics (each site updated at rate 1) of the Ising model on the L × L torus at the critical temperature, the inverse spectral gap and the mixing time are L^{z+o(1)} for an exponent z, numerically z ≈ 2.17. Prove that z exists, determine it, and show it is the same for every local reversible single-spin dynamics whose rates are bounded above and below uniformly.",
 c="This is the dynamic exponent of model A in the Hohenberg–Halperin classification; no closed form is predicted.",
 src="P. C. Hohenberg and B. I. Halperin, Theory of dynamic critical phenomena, Rev. Mod. Phys. 49 (1977); E. Lubetzky and A. Sly, Critical Ising on the square lattice mixes in polynomial time, Comm. Math. Phys. 313 (2012)",
 why="z is the basic exponent of critical slowing down, which controls the cost of simulating critical systems; in two dimensions every static exponent is known exactly but the dynamic one is not.",
 st="Lubetzky and Sly (2012) proved polynomial mixing at criticality, L^C for some C. The lower bound z ≥ 2 is proved (Masaoka–Soejima–Watanabe, arXiv:2502.09908), improving z ≥ 7/4 = 2 − η. Numerical estimates give z ≈ 2.1665 (Nightingale–Blöte, Phys. Rev. Lett. 76 (1996) 4548). Existence and value are open.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T131", d="SM", t="The Coulomb phase of the three-dimensional dimer model",
 s="For uniformly random dimer coverings (perfect matchings) of large boxes or tori in Z^3, dimer–dimer correlations decay like |x|^{−3} with a dipolar angular dependence, and the associated flux field converges to a Gaussian (Coulomb) field.",
 c="In two dimensions the analogous statement follows from Kasteleyn's determinantal solution; in three dimensions there is no such solution.",
 src="D. A. Huse, W. Krauth, R. Moessner and S. L. Sondhi, Coulomb and liquid dimer models in three dimensions, Phys. Rev. Lett. 91 (2003)",
 why="The Coulomb phase is the basic example of an emergent gauge field in classical statistical mechanics (spin ice, frustrated magnets), and the three-dimensional dimer model is its simplest lattice instance.",
 st="A variational principle and large deviations for the height-like flux of three-dimensional dimers are proved (Chandgotia–Sheffield–Wolfram, arXiv:2304.08468), and macroscopic loops in related three-dimensional loop and double-dimer models are known (Quitmann–Taggi, arXiv:2201.04047 and 2206.08284). The power-law correlations and the Gaussian limit are open.",
 n="Status updated after the w673 audit (14 Oct). Fame borderline in that audit; kept for now."),
dict(id="T132", d="GF", t="Metric scaling limits of decorated random planar maps",
 s="Random planar maps weighted by a critical FK model with 0 ≤ q < 4 (q = 0 is the map decorated by a uniform spanning tree, q = 1 the uniform map, q = 2 the critical Ising map), with distances rescaled by n^{−1/d_γ+o(1)}, converge in the Gromov–Hausdorff–Prokhorov topology to the γ-Liouville quantum gravity metric sphere, where q = 2 + 2cos(πγ²/2) (γ = √2, √(8/3), √3 in the three cases).",
 c="Only the uniform case γ = √(8/3) (the Brownian map) is known; the exponent d_γ for other γ is itself unknown (T037). For q > 4 the maps are in another phase, with a continuum-random-tree limit (Feng, arXiv:2311.06235). This row asks for metric convergence, while T023 asks for convergence under conformal embedding.",
 src="J. Miller and S. Sheffield, Liouville quantum gravity and the Brownian map I, Invent. Math. 219 (2020) 75–152; J. Ding, J. Dubédat, A. Dunlap and H. Falconet, Tightness of Liouville first passage percolation for γ ∈ (0,2), Publ. Math. IHÉS 132 (2020)",
 why="It would identify the geometry of random surfaces carrying the main critical models with LQG, the continuum theory physicists use for two-dimensional quantum gravity, and would make d_γ a measurable growth exponent of discrete maps.",
 st="Uniform maps converge to the Brownian map (Le Gall 2013; Miermont 2013), identified with √(8/3)-LQG (Miller–Sheffield). The γ-LQG metric exists and is unique for every γ ∈ (0,2) (Ding–Dubédat–Dunlap–Falconet 2020; Gwynne–Miller 2021). For decorated maps only distance-exponent bounds are known (Ding–Gwynne, Comm. Math. Phys. 374 (2020); Gwynne–Holden–Sun, arXiv:1711.00723); for spanning-tree-decorated maps a directed distance scales as n^{1/3} (arXiv:2609.22514), which is not the graph distance. Open for every γ ≠ √(8/3). Partial claim, 14 Nov 2026: the OpenAI math release preprint 'Metric-measure limits of subcritical FK and spanning-tree planar maps' (24 Sep 2026, github.com/openai/math) claims convergence of the graph metric with normalized degree measure to the unit-area LQG sphere for every fixed 0<q<4 and for spanning-tree-weighted maps, with an unspecified deterministic distance scale; it does not assert the n^(-1/d_gamma+o(1)) normalization, and uniform vertex measure would need a separate argument. These are unrefereed AI-written claims; this records their scope, not a check of the proofs.",
 n="Statement revised after the w673 audit (14 Oct)."),
dict(id="T133", d="GF", t="The arctic curve of the six-vertex model with domain-wall boundary conditions",
 s="For the six-vertex model with domain-wall boundary conditions on an n × n square, in the disordered regime −1 < Δ < 1, the boundary between the frozen and disordered regions converges after rescaling by n to the curve predicted by Colomo and Pronko, and recovered by the tangent method of Colomo and Sportiello; the analogous prediction holds in the antiferroelectric regime Δ < −1.",
 c="The predictions are explicit algebraic or transcendental curves depending on the weights; at Δ = 0 (free fermions) the curve is an ellipse, the arctic circle of domino tilings for equal weights.",
 src="F. Colomo and A. G. Pronko, The limit shape of large alternating sign matrices, SIAM J. Discrete Math. 24 (2010); F. Colomo and A. Sportiello, Arctic curves of the six-vertex model on generic domains: the tangent method, J. Stat. Phys. 164 (2016)",
 why="The six-vertex model is the basic integrable model outside free fermions; its limit shapes test whether the variational and tangent-method predictions hold beyond the determinantal case, and uniformly random alternating sign matrices are a special case.",
 st="At Δ = 0 the arctic circle is known (Jockusch–Propp–Shor 1995). At the ice point Δ = 1/2, which includes uniformly random alternating sign matrices, Aggarwal (arXiv:1812.03847, 2020) proved the Colomo–Pronko arctic curve for domain-wall boundary conditions, and the predicted boundaries for more general three-bundle domains. Other values of Δ are open; fluctuations of the height function are T063.",
 n="Statement revised after the w673 audit (14 Oct). Fame borderline in that audit; kept for now."),
dict(id='T134',
 x='Moved on 12 Nov 2026 to the list of open problems in mathematics generally (06_math_research/top200_general_2026_11_10, seed_from_probability.tsv): Diagonal Ramsey lower bound: combinatorics.',
 d='RG',
 t='An exponential improvement of the random-graph lower bound for diagonal Ramsey numbers',
 s='Is there ε > 0 such that R(k, k) ≥ (√2 + ε)^k for all large k? Equivalently, are there graphs on (√2 + ε)^k vertices with no clique and no independent set of size k?',
 c="Erdős's 1947 bound comes from the random graph G(n, 1/2), and no construction, random or explicit, has beaten its exponential rate. Erdős offered prizes for the existence and the value of lim R(k, k)^{1/k} (100 dollars for existence, 10,000 for the value; Chung and Graham, Erdős on Graphs, A K Peters 1998).",
 src='P. Erdős, Some remarks on the theory of graphs, Bull. Amer. Math. Soc. 53 (1947)',
 why='This is the founding problem of the probabilistic method: the random graph is the best known Ramsey graph, and an exponential improvement would need a genuinely new source of structure or randomness.',
 st="The lower bound R(k, k) ≥ (1 + o(1)) (√2 k/e) 2^{k/2} (Spencer 1975, by the local lemma) is a factor 2 over Erdős's. The upper bound was improved exponentially to (4 − ε)^k (Campos–Griffiths–Morris–Sahasrabudhe 2023), then to about 3.8^k (Gupta–Ndiaye–Norin–Wei, arXiv:2407.19026), and arXiv:2609.14525 claims 3.69507^k. No exponential improvement of the lower bound is known; explicit constructions are far weaker.",
 n='Status updated after the w673 audit (14 Oct).'),
]
